/**
 * Procedurally generates 4 Board-Standard MCQs for every word in the vocabulary list.
 * 1. Synonym Question (🔄)
 * 2. Antonym Question (🔀)
 * 3. English Definition Question (📖)
 * 4. Bangla Meaning Question (🇧🇩)
 */
export function buildQuestionsDatabase() {
  const list = [];
  const total = hscVocabularyList.length;

  hscVocabularyList.forEach((item, idx) => {
    const word = item.word;
    const pos = item.partsOfSpeech || 'Word';
    const primarySyn = (item.synonyms || '').split(',')[0].trim();
    const primaryAnt = (item.antonyms || '').split(',')[0].trim();
    const boardTag = item.boardExamTag || 'Unit 1 • Lesson 1';

    // Distractor helpers
    const getOtherSyns = (excludeIdx, count = 3) => {
      const distractors = [];
      let step = 1;
      while (distractors.length < count) {
        const candidate = hscVocabularyList[(excludeIdx + step * 7) % total];
        const cSyn = (candidate.synonyms || '').split(',')[0].trim();
        if (cSyn && cSyn !== primarySyn && !distractors.includes(cSyn)) {
          distractors.push(cSyn);
        }
        step++;
      }
      return distractors;
    };

    const getOtherAnts = (excludeIdx, count = 3) => {
      const distractors = [];
      let step = 1;
      while (distractors.length < count) {
        const candidate = hscVocabularyList[(excludeIdx + step * 11) % total];
        const cAnt = (candidate.antonyms || '').split(',')[0].trim();
        if (cAnt && cAnt !== primaryAnt && !distractors.includes(cAnt)) {
          distractors.push(cAnt);
        }
        step++;
      }
      return distractors;
    };

    const getOtherDefs = (excludeIdx, count = 3) => {
      const distractors = [];
      let step = 1;
      while (distractors.length < count) {
        const candidate = hscVocabularyList[(excludeIdx + step * 13) % total];
        const cDef = candidate.englishMeaning;
        if (cDef && cDef !== item.englishMeaning && !distractors.includes(cDef)) {
          distractors.push(cDef);
        }
        step++;
      }
      return distractors;
    };

    const getOtherBangla = (excludeIdx, count = 3) => {
      const distractors = [];
      let step = 1;
      while (distractors.length < count) {
        const candidate = hscVocabularyList[(excludeIdx + step * 17) % total];
        const cBn = candidate.bengaliMeaning;
        if (cBn && cBn !== item.bengaliMeaning && !distractors.includes(cBn)) {
          distractors.push(cBn);
        }
        step++;
      }
      return distractors;
    };

    // 1. Synonym Question
    if (primarySyn) {
      const dist = getOtherSyns(idx, 3);
      const opts = [primarySyn, ...dist].sort(() => Math.random() - 0.5);
      list.push({
        id: `${item.id}-syn`,
        vocabId: item.id,
        category: 'synonyms',
        type: 'synonym',
        categoryLabel: 'Synonym',
        word: item.word,
        partsOfSpeech: pos,
        question: `What is the closest SYNONYM of the word "${word}"?`,
        questionBn: `"${word}" (${item.bengaliMeaning}) শব্দটির সমার্থক শব্দ (Synonym) কোনটি?`,
        options: opts,
        correctAnswer: primarySyn,
        explanation: `"${word}" means "${item.englishMeaning}". Closest synonym is "${primarySyn}". Context sentence: "${item.exampleSentence}"`,
        explanationBn: `"${word}" শব্দের অর্থ "${item.bengaliMeaning}"। এর সমার্থক শব্দ হলো "${primarySyn}"। পাঠ্যবইয়ের বাক্য: "${item.exampleSentence}"`,
        exampleSentence: item.exampleSentence,
        unit: item.unit,
        lesson: item.lesson,
        boardExamTag: boardTag,
        sources: item.sources || [item.unit],
        isCrossReferenced: item.isCrossReferenced || false,
        crossReferencedWords: item.crossReferencedWords || [],
        difficulty: 'Medium'
      });
    }

    // 2. Antonym Question
    if (primaryAnt) {
      const dist = getOtherAnts(idx, 3);
      const opts = [primaryAnt, ...dist].sort(() => Math.random() - 0.5);
      list.push({
        id: `${item.id}-ant`,
        vocabId: item.id,
        category: 'antonyms',
        type: 'antonym',
        categoryLabel: 'Antonym',
        word: item.word,
        partsOfSpeech: pos,
        question: `What is the ANTONYM of the word "${word}"?`,
        questionBn: `"${word}" (${item.bengaliMeaning}) শব্দটির বিপরীতার্থক শব্দ (Antonym) কোনটি?`,
        options: opts,
        correctAnswer: primaryAnt,
        explanation: `The opposite of "${word}" is "${primaryAnt}". Context: "${item.exampleSentence}"`,
        explanationBn: `"${word}" শব্দের বিপরীত শব্দ হলো "${primaryAnt}"। পাঠ্যবইয়ের বাক্য: "${item.exampleSentence}"`,
        exampleSentence: item.exampleSentence,
        unit: item.unit,
        lesson: item.lesson,
        boardExamTag: boardTag,
        sources: item.sources || [item.unit],
        isCrossReferenced: item.isCrossReferenced || false,
        crossReferencedWords: item.crossReferencedWords || [],
        difficulty: 'Hard'
      });
    }

    // 3. English Definition Question
    if (item.englishMeaning) {
      const dist = getOtherDefs(idx, 3);
      const opts = [item.englishMeaning, ...dist].sort(() => Math.random() - 0.5);
      list.push({
        id: `${item.id}-def`,
        vocabId: item.id,
        category: 'english_meaning',
        type: 'english_meaning',
        categoryLabel: 'English Meaning',
        word: item.word,
        partsOfSpeech: pos,
        question: `What is the English definition of "${word}" (${pos})?`,
        questionBn: `"${word}" (${pos}) শব্দটির ইংরেজি সংজ্ঞা কোনটি?`,
        options: opts,
        correctAnswer: item.englishMeaning,
        explanation: `Definition: ${item.englishMeaning}. Synonyms: ${item.synonyms}. Context: "${item.exampleSentence}"`,
        explanationBn: `সংজ্ঞা: ${item.englishMeaning}। সমার্থক শব্দ: ${item.synonyms}। পাঠ্যবইয়ের বাক্য: "${item.exampleSentence}"`,
        exampleSentence: item.exampleSentence,
        unit: item.unit,
        lesson: item.lesson,
        boardExamTag: boardTag,
        sources: item.sources || [item.unit],
        isCrossReferenced: item.isCrossReferenced || false,
        crossReferencedWords: item.crossReferencedWords || [],
        difficulty: 'Medium'
      });
    }

    // 4. Bangla Meaning Question
    if (item.bengaliMeaning) {
      const dist = getOtherBangla(idx, 3);
      const opts = [item.bengaliMeaning, ...dist].sort(() => Math.random() - 0.5);
      list.push({
        id: `${item.id}-bn`,
        vocabId: item.id,
        category: 'bangla_meaning',
        type: 'bangla_meaning',
        categoryLabel: 'Bangla Meaning',
        word: item.word,
        partsOfSpeech: pos,
        question: `"${word}" শব্দটির সঠিক বাংলা অর্থ কোনটি?`,
        questionBn: `"${word}" শব্দটির পাঠ্যবই অনুযায়ী সঠিক বাংলা অর্থ কোনটি?`,
        options: opts,
        correctAnswer: item.bengaliMeaning,
        explanation: `বাংলা অর্থ: ${item.bengaliMeaning}। ইংরেজি অর্থ: ${item.englishMeaning}। পাঠ্যবইয়ের বাক্য: "${item.exampleSentence}"`,
        explanationBn: `"${word}" শব্দটির পাঠ্যবই অনুযায়ী সঠিক বাংলা অর্থ হলো "${item.bengaliMeaning}"।`,
        exampleSentence: item.exampleSentence,
        unit: item.unit,
        lesson: item.lesson,
        boardExamTag: boardTag,
        sources: item.sources || [item.unit],
        isCrossReferenced: item.isCrossReferenced || false,
        crossReferencedWords: item.crossReferencedWords || [],
        difficulty: 'Easy'
      });
    }
  });

  return list;
}

export const hscQuestionsList = buildQuestionsDatabase();

export function smartInterleaveQuestions(rawQuestions = []) {
  if (!rawQuestions || rawQuestions.length <= 1) return rawQuestions;

  const wordBuckets = {};
  rawQuestions.forEach((q) => {
    const key = q.vocabId || q.word;
    if (!wordBuckets[key]) wordBuckets[key] = [];
    wordBuckets[key].push(q);
  });

  const keys = Object.keys(wordBuckets);
  const shuffledKeys = [...keys].sort(() => Math.random() - 0.5);

  const interleaved = [];
  let hasMore = true;
  let round = 0;

  while (hasMore) {
    hasMore = false;
    for (const key of shuffledKeys) {
      if (wordBuckets[key].length > round) {
        interleaved.push(wordBuckets[key][round]);
        hasMore = true;
      }
    }
    round++;
  }

  return interleaved;
}

export function matchesUnitAndLesson(item, unitId, lessonId) {
  if (!item) return false;
  if (!unitId || unitId === 'all') return true;
  const uNum = typeof unitId === 'string' && unitId.startsWith('unit-')
    ? unitId.replace('unit-', '')
    : String(unitId).replace(/[^0-9]/g, '');
  const sourcesStr = Array.isArray(item.sources) ? item.sources.join(' ') : '';
  const itemTag = (item.boardExamTag || '') + ' ' + (item.unit || '') + ' ' + (item.id || '') + ' ' + sourcesStr;
  const unitRegex = new RegExp('\\bUnit\\s*' + uNum + '\\b|vocab-u' + uNum + '(-|\\b)', 'i');
  if (!unitRegex.test(itemTag)) return false;
  if (!lessonId || lessonId === 'all') return true;
  const lNum = typeof lessonId === 'string' && lessonId.includes('-l')
    ? lessonId.split('-l')[1]
    : String(lessonId).replace(/[^0-9]/g, '');
  const lessonRegex = new RegExp('(?:•|:|\\b)Lesson\\s*' + lNum + '(\\b|\\s|\\()|vocab-u' + uNum + '-l' + lNum + '(\\b|-)', 'i');
  return lessonRegex.test(itemTag);
}

export function getFilteredCategoryQuestions(
  categories = ['synonyms', 'antonyms', 'english_meaning', 'bangla_meaning'],
  lessonId = null,
  unitNumber = null
) {
  const activeCategories = categories.length > 0
    ? categories
    : ['synonyms', 'antonyms', 'english_meaning', 'bangla_meaning'];

  const matched = hscQuestionsList.filter((q) => {
    return activeCategories.includes(q.category);
  });

  return smartInterleaveQuestions(matched);
}

